#!/usr/bin/env node
/**
 * Emit both CI definitions from ci/pipeline.mjs — and prove the committed ones are current.
 *
 *   node scripts/gen-ci.mjs            write .github/workflows/nightbark.yml + azure-pipelines.yml
 *   node scripts/gen-ci.mjs --check    exit 1 if either committed file differs from the definition
 *
 * ⚠️ `--check` is the load-bearing half. A generated file that is committed will be hand-edited
 * eventually, and from that moment the "single source of truth" is a lie that nobody can see. The
 * check runs in the selftest, so the drift fails a build rather than being discovered months later
 * by someone wondering why their change to the YAML keeps vanishing.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { pipeline as P } from '../ci/pipeline.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

/**
 * Quote EVERY emitted scalar.
 *
 * ⚠️ The first version emitted labels and commands bare, and produced INVALID YAML the moment a
 * label contained a colon — `ADR-0001: no client-identifying content` broke the whole workflow.
 * Caught by parsing the output, which is the only reason it did not ship.
 *
 * The fix is not "avoid colons in labels", because the next person will write one. Anything emitted
 * into a YAML scalar position gets quoted: labels, and commands too, since those routinely contain
 * `"` (a --test glob) and can start with `*`, both of which break a bare scalar just as badly.
 */
function y(s) {
    return `'${String(s).replace(/'/g, "''")}'`;   // single-quoted YAML: only ' needs escaping
}
const BANNER = (file) => `# GENERATED by scripts/gen-ci.mjs from ci/pipeline.mjs — DO NOT EDIT BY HAND.
# Edit the definition and re-run \`npm run ci:gen\`. \`npm run ci:check\` fails the build if this
# file and the definition disagree, so a hand edit here will be caught rather than silently lost.
# target: ${file}
`;

/** GitHub Actions — uses the Checks API via SARIF upload, which is this platform's best trick. */
function githubWorkflow() {
    const steps = P.steps.map((s) => {
        const lines = [
            `      - name: ${y(s.label)}`,
            `        run: ${y(s.run)}`,
        ];
        if (!s.failsBuild) lines.push('        continue-on-error: true');
        return lines.join('\n');
    });

    const sarifStep = P.steps.find((s) => s.sarif);
    const extras = [];
    if (sarifStep) {
        // ⚠️ THE WHOLE POINT OF SARIF: findings annotated on the pull-request diff, where a reviewer
        // already is — rather than in an artifact nobody remembers to download.
        extras.push(`      - name: ${y('Annotate findings on the diff (SARIF -> Code Scanning)')}
        if: always()
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: ${y(sarifStep.sarif)}
        continue-on-error: true`);
    }
    const artifactStep = P.steps.find((s) => s.artifact);
    if (artifactStep) {
        extras.push(`      - name: ${y('Keep the SARIF as an artifact')}
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: ${y(artifactStep.artifact.name)}
          path: ${y(artifactStep.artifact.path)}`);
    }

    return `${BANNER('.github/workflows/nightbark.yml')}
name: ${y(P.name)}

on:
  push:
    branches: [${P.triggers.push.join(', ')}]
  pull_request:
    branches: [${P.triggers.pullRequest.join(', ')}]

permissions:
  contents: read
  security-events: write   # required to upload SARIF to Code Scanning

jobs:
  verify:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: ${y(P.node)}
${steps.join('\n')}
${extras.join('\n')}
`;
}

/** Azure Pipelines — same intent, this platform's idioms. */
function azurePipeline() {
    const steps = P.steps.map((s) => [
        `  - script: ${y(s.run)}`,
        `    displayName: ${y(s.label)}`,
        ...(s.failsBuild ? [] : ['    continueOnError: true']),
    ].join('\n'));

    const artifactStep = P.steps.find((s) => s.artifact);
    const extras = artifactStep ? [`  - task: PublishPipelineArtifact@1
    displayName: ${y('Keep the SARIF as an artifact')}
    condition: always()
    inputs:
      targetPath: ${y(artifactStep.artifact.path)}
      artifact: ${y(artifactStep.artifact.name)}`] : [];

    return `${BANNER('azure-pipelines.yml')}
trigger:
  branches:
    include:
${P.triggers.push.map((b) => `      - ${b}`).join('\n')}

pr:
  branches:
    include:
${P.triggers.pullRequest.map((b) => `      - ${b}`).join('\n')}

pool:
  vmImage: ubuntu-latest

steps:
  - task: NodeTool@0
    displayName: ${y('Use Node ' + P.node)}
    inputs:
      versionSpec: ${y(P.node)}

${steps.join('\n')}
${extras.join('\n')}
`;
}

const OUTPUTS = [
    { path: '.github/workflows/nightbark.yml', render: githubWorkflow },
    { path: 'azure-pipelines.yml', render: azurePipeline },
];

const check = process.argv.includes('--check');
let drifted = 0;

for (const { path, render } of OUTPUTS) {
    const abs = join(ROOT, path);
    const wanted = render();
    if (check) {
        let actual = null;
        try { actual = readFileSync(abs, 'utf8'); } catch { /* missing */ }
        if (actual !== wanted) {
            drifted++;
            console.log(`  ✖  ${path} ${actual === null ? 'is MISSING' : 'has DRIFTED from ci/pipeline.mjs'}`);
        } else {
            console.log(`  ok  ${path} matches ci/pipeline.mjs`);
        }
    } else {
        mkdirSync(dirname(abs), { recursive: true });
        writeFileSync(abs, wanted);
        console.log(`  wrote ${path}`);
    }
}

if (check && drifted) {
    console.log(`\n  ${drifted} generated CI file(s) out of date. Run \`npm run ci:gen\` and commit the result.`);
    console.log('  A hand edit to a generated file is lost on the next regeneration, which is why this fails the build.\n');
    process.exit(1);
}
if (check) console.log('\n  both CI definitions are current\n');
